import{_ as a,o as s,c as r,a2 as d}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"开源许可声明","description":"AgoraIn 各组成部分的开源/闭源边界、第三方组件许可与常见误解澄清","frontmatter":{"title":"开源许可声明","description":"AgoraIn 各组成部分的开源/闭源边界、第三方组件许可与常见误解澄清"},"headers":[],"relativePath":"license.md","filePath":"license.md","lastUpdated":1792286071000}'),o={name:"license.md"};function n(l,t,e,i,h,g){return s(),r("div",null,[...t[0]||(t[0]=[d(`<h1 id="开源许可声明" tabindex="-1">开源许可声明 <a class="header-anchor" href="#开源许可声明" aria-label="Permalink to &quot;开源许可声明&quot;">​</a></h1><blockquote><p>这份声明只为把一件事说清楚：<strong>AgoraIn 的哪些部分是开源的、哪些是闭源的，为什么可以这样组合。</strong> 如果你看到&quot;闭源软件里出现了 GPL 项目&quot;，请先读完本页再判断。</p></blockquote><h2 id="一、一张表看清边界" tabindex="-1">一、一张表看清边界 <a class="header-anchor" href="#一、一张表看清边界" aria-label="Permalink to &quot;一、一张表看清边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组成部分</th><th>许可</th><th>是否提供源码</th></tr></thead><tbody><tr><td><strong>AgoraIn v4 服务端</strong>（ASP.NET Core 服务、Web 管理面板、移动端 App、桌面端、家长端小程序）</td><td><strong>闭源商业授权</strong></td><td>❌ 不提供（商业资产）</td></tr><tr><td><strong>AgoraIn v3.2 及更早版本</strong>（AgoraInPro）</td><td><strong>GPLv3 开源</strong></td><td>✅ 已开源，归档文档见 <a href="/v3.2/">v3.2</a> / <a href="/v2.8/">v2.8</a> / <a href="/v2.7/">v2.7</a></td></tr><tr><td><strong>定制版 ClassIsland（AgoraIn 集控客户端）</strong></td><td><strong>GPL-3.0 开源</strong></td><td>✅ 随二进制提供完整对应源码</td></tr><tr><td><strong>集控插件包（服务端 <code>.agp</code>）</strong></td><td><strong>GPL-3.0 开源</strong></td><td>✅ 随二进制提供完整对应源码</td></tr><tr><td>一体机插件（ClassIsland <code>.cipx</code>）</td><td>闭源插件（仅调用平台 HTTP 接口）</td><td>❌ 不提供</td></tr><tr><td>教学模式中的物理 / 化学实验元件图形</td><td>本项目自绘矢量图（自有版权）</td><td>随前端页面分发</td></tr></tbody></table><p><strong>要点</strong>：v4 起，<strong>平台主体转为闭源商业授权</strong>；而与 ClassIsland 相关的两件东西 （定制版客户端、服务端集控插件）<strong>以 GPL-3.0 开源</strong>，因为它们是基于 ClassIsland（GPL-3.0）的衍生作品 —— <strong>我们遵守 GPL，而不是绕过它</strong>。</p><h2 id="二、为什么-闭源服务端-gpl-插件-可以共存" tabindex="-1">二、为什么&quot;闭源服务端 + GPL 插件&quot;可以共存 <a class="header-anchor" href="#二、为什么-闭源服务端-gpl-插件-可以共存" aria-label="Permalink to &quot;二、为什么&quot;闭源服务端 + GPL 插件&quot;可以共存&quot;">​</a></h2><p>这是最容易被误解的地方。我们的做法是<strong>动态加载 + 中立契约层</strong>，而不是静态链接：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>闭源 AgoraIn.Server ──引用──► AgoraIn.Plugin.Abstractions（MIT，只依赖 BCL）</span></span>
<span class="line"><span>        │                                    ▲</span></span>
<span class="line"><span>        │ 运行时 AssemblyLoadContext 动态加载  │ 插件只引用契约层</span></span>
<span class="line"><span>        └──────────► 集控插件（GPL-3.0）──────┘</span></span>
<span class="line"><span>                     （独立程序集，不复制服务端代码）</span></span></code></pre></div><ul><li>服务端与插件之间<strong>只有一个 MIT 许可的接口程序集</strong>（<code>AgoraIn.Plugin.Abstractions</code>）， 插件完全看不到服务端内部实现，也不包含服务端任何代码；</li><li>插件以<strong>独立程序集</strong>形式在运行期被加载（<code>.agp</code> 包），可以随时停用、卸载；</li><li>因此插件是<strong>独立作品</strong>，其 GPL 义务<strong>不延伸到闭源服务端</strong>；反过来，服务端也不会因为加载它而被迫开源。</li></ul><blockquote><p>这条边界不是口头承诺，而是工程上的硬约束：插件包里禁止携带契约程序集、 服务端工程不引用任何 GPL 程序集、GPL 系插件安装时必须显式确认并声明源码地址。</p></blockquote><h2 id="三、定制版-classisland-的合规做法" tabindex="-1">三、定制版 ClassIsland 的合规做法 <a class="header-anchor" href="#三、定制版-classisland-的合规做法" aria-label="Permalink to &quot;三、定制版 ClassIsland 的合规做法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>GPL 要求</th><th>我们的做法</th></tr></thead><tbody><tr><td>衍生作品须以 GPL 发布</td><td>定制版整体 GPL-3.0，安装包内附 <code>LICENSE</code> 与版权声明</td></tr><tr><td>须提供完整对应源码</td><td>源码随二进制提供（下载页与仓库同时给出获取方式）</td></tr><tr><td>须保留上游版权与许可声明</td><td>保留 ClassIsland 原有版权、许可与贡献者信息；关于页可查</td></tr><tr><td>不得暗示官方背书</td><td>明确标注&quot;非官方定制版，与 ClassIsland 官方团队无隶属关系&quot;</td></tr></tbody></table><p><strong>关于&quot;定制&quot;到底改了什么</strong>：新增 AgoraIn 集控客户端（注册 / 心跳 / 指令轮询执行 / 回执 / 呼叫）、 集控连接设置入口、关于页的 AgoraIn 品牌信息；其余功能与上游一致。</p><h2 id="四、第三方组件" tabindex="-1">四、第三方组件 <a class="header-anchor" href="#四、第三方组件" aria-label="Permalink to &quot;四、第三方组件&quot;">​</a></h2><p>平台与客户端使用到的第三方组件均按其自身许可证分发，主要包括（不完全列举）：</p><table tabindex="0"><thead><tr><th>组件</th><th>许可</th><th>用在哪</th></tr></thead><tbody><tr><td>ASP.NET Core / Entity Framework Core / SignalR</td><td>MIT</td><td>服务端</td></tr><tr><td>pdf.js</td><td>Apache-2.0</td><td>教学模式 PDF 渲染</td></tr><tr><td>@microsoft/signalr（浏览器客户端）</td><td>MIT</td><td>白板 / 集控实时通道</td></tr><tr><td>Avalonia / FluentAvalonia</td><td>MIT</td><td>桌面端与定制版 ClassIsland 界面框架</td></tr><tr><td>QRCoder、MailKit、SkiaSharp、YamlDotNet</td><td>MIT</td><td>二维码、邮件、图像、档案解析</td></tr><tr><td>ZXing.Net</td><td>Apache-2.0</td><td>条码识别</td></tr><tr><td>ClassIsland 及其上游组件</td><td>GPL-3.0</td><td>定制版 ClassIsland</td></tr></tbody></table><h2 id="五、素材与商标" tabindex="-1">五、素材与商标 <a class="header-anchor" href="#五、素材与商标" aria-label="Permalink to &quot;五、素材与商标&quot;">​</a></h2><ul><li><strong>教学模式中的物理元件与化学仪器图形，全部为本项目自绘 SVG 矢量图</strong>， 仿真逻辑（电路用改进节点法求解、化学用反应规则表）亦为自研，<strong>未使用任何第三方实验素材</strong>；</li><li>AgoraIn 名称与标志为本项目自有；&quot;ClassIsland&quot; 为其项目方所有， 本项目对 ClassIsland 的使用仅限于遵循 GPL-3.0 的衍生与引用，<strong>不代表其官方</strong>；</li><li>文档与宣传片中的界面截图均来自本项目产品实际界面。</li></ul><h2 id="六、常见误解澄清" tabindex="-1">六、常见误解澄清 <a class="header-anchor" href="#六、常见误解澄清" aria-label="Permalink to &quot;六、常见误解澄清&quot;">​</a></h2><p><strong>&quot;闭源商业软件里集成了 GPL 代码&quot;</strong> —— 没有。GPL 代码只存在于独立的插件包与定制版客户端里， 二者与闭源服务端通过 HTTP 协议通信，互不链接。</p><p><strong>&quot;既然是 GPL，那服务端也应该开源&quot;</strong> —— GPL 的传染性作用于&quot;衍生作品&quot;。 服务端不是 ClassIsland 的衍生作品（不含其代码、不链接其程序集），因此没有开源义务。</p><p><strong>&quot;用了 GPL 插件就等于整体 GPL&quot;</strong> —— 不等于。聚合（aggregation）与动态加载是业界公认的独立作品边界。</p><p><strong>&quot;v3.2 开源过，v4 怎么就闭源了&quot;</strong> —— v3.2 及更早的代码仍以 GPLv3 开源（归档可查）； v4 是<strong>重写的新代码库</strong>，自 v4 起采用商业授权。旧版本不会撤回其开源许可。</p><h2 id="七、获取源码与反馈" tabindex="-1">七、获取源码与反馈 <a class="header-anchor" href="#七、获取源码与反馈" aria-label="Permalink to &quot;七、获取源码与反馈&quot;">​</a></h2><ul><li>定制版 ClassIsland / 集控插件源码：随对应安装包提供，或通过<a href="/download.html">下载中心</a>页面的源码链接获取；</li><li>上游 ClassIsland：<a href="https://github.com/ClassIsland/ClassIsland" target="_blank" rel="noreferrer">https://github.com/ClassIsland/ClassIsland</a>；</li><li>对许可有疑问、或发现我们有任何不合规之处，欢迎通过企业微信客服指出，我们会第一时间修正。</li></ul><h2 id="相关阅读" tabindex="-1">相关阅读 <a class="header-anchor" href="#相关阅读" aria-label="Permalink to &quot;相关阅读&quot;">​</a></h2><ul><li><a href="/custom-classisland.html">定制版 ClassIsland</a> · <a href="/teaching.html">教学模式</a> · <a href="/download.html">下载中心</a></li></ul>`,27)])])}const u=a(o,[["render",n]]);export{p as __pageData,u as default};
